let store,state=emptyState(),user=null,busy=false,route='home',recordId='',mode='',search='',filter='',calendarMode='month',calendarDate=today(),listMode='list',objectUrls=[],pageTitle='',pageDescription='',pageActions='',pageTabs='',notesOpen=false,noteQuery='',noteFilter='all',editingNoteId='',clientPanelOpen=false,createPanelKind='',clientType='person',clientTypeFilter='all',clientTagFilter='',clientSort='recent',clientDuplicateOverride=false,pendingOrderClientId='',salesDate='all',salesSort='recent';
function notice(text,error=false){const n=$('#notice');n.textContent=text;n.className='show';n.setAttribute('role',error?'alert':'status');clearTimeout(notice.timer);notice.timer=setTimeout(()=>n.className='',6500);}
function ask(message,withReason=false){return new Promise(resolve=>{const previous=document.activeElement,dialog=document.createElement('dialog');dialog.className='confirm-dialog';dialog.innerHTML=`<h2>Confirmar cambio</h2><p>${esc(message)}</p>${withReason?'<label class="field"><span>Motivo</span><textarea id="confirmation-reason" required></textarea></label>':''}<div class="actions section-space"><button type="button" data-confirm="cancel">Cancelar</button><button type="button" class="primary" data-confirm="ok">Confirmar</button></div>`;const finish=value=>{dialog.close();dialog.remove();previous?.focus();resolve(value);};dialog.addEventListener('cancel',e=>{e.preventDefault();finish(null);});dialog.addEventListener('click',e=>{const choice=e.target.dataset.confirm;if(choice==='cancel')finish(null);if(choice==='ok'){const reason=dialog.querySelector('textarea');if(reason&&!reason.value.trim()){reason.reportValidity();reason.focus();return;}finish(withReason?reason.value.trim():true);}});document.body.append(dialog);dialog.showModal();dialog.querySelector(withReason?'textarea':'button').focus();});}
function askQuoteAcceptance(){return new Promise(resolve=>{const previous=document.activeElement,dialog=document.createElement('dialog');dialog.className='confirm-dialog quote-accept-dialog';dialog.innerHTML='<h2>La cotización fue aceptada</h2><p>¿Qué deseas hacer ahora?</p><div class="quote-accept-options"><button type="button" data-choice="both">Crear pedido y factura</button><button type="button" data-choice="order">Crear solo el pedido</button><button type="button" data-choice="keep">Mantener únicamente como aceptada</button><button type="button" data-choice="cancel">Cancelar</button></div>';const finish=value=>{dialog.close();dialog.remove();previous?.focus();resolve(value);};dialog.addEventListener('cancel',e=>{e.preventDefault();finish(null);});dialog.addEventListener('click',e=>{if(e.target.dataset.choice)finish(e.target.dataset.choice==='cancel'?null:e.target.dataset.choice);});document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-choice=both]').focus();});}
function errorMessage(e){if(e?.code?.startsWith('auth/'))return 'No pudimos iniciar sesión. Revisa el correo y la contraseña, o recupera tu acceso.';if(e?.code==='permission-denied'||e?.code==='storage/unauthorized'||e?.message==='PANEL_ACCESS_PENDING')return 'El acceso privado del panel todavía necesita habilitación en Firebase. Tus datos no se guardarán en espacios públicos.';return e?.message||'No se pudo completar la acción. Vuelve a intentarlo.';}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
const btn=(label,action,attrs='',primary=false)=>`<button type="button" data-action="${action}" ${attrs} class="${primary?'primary':''}">${label}</button>`;
function displayField(f,value){if(f.type!=='select')return value;const option=f.options.find(o=>Array.isArray(o)?o[0]===value:o===value);return Array.isArray(option)?option[1]:value;}
const link=(kind,r)=>kind==='movements'?esc(r.name):`<a href="#${kind}/${r.id}">${esc(r.number||r.name)}</a>`;
const badge=status=>`<span class="badge ${['pagada','aprobada','entregado','completada'].includes(status)?'good':['vencida','pendiente','alta'].includes(status)?'warn':''}">${esc(status)}</span>`;
function loginScreen(message=''){$('#app').innerHTML=`<main id="main" class="login"><section class="login-card"><h1 class="brand-script">Life Deco Art</h1><h2>Tu espacio de trabajo</h2><p class="muted">Entra con tu cuenta privada del hub.</p><form id="login-form"><label>Correo<input type="email" name="email" autocomplete="username" required></label><label>Contraseña<input type="password" name="password" autocomplete="current-password" required></label><button class="primary" type="submit">Entrar al panel</button>${btn('Recuperar acceso','reset')}</form><div id="login-error" ${message?'class="error" role="alert"':''}>${esc(message)}</div><p class="sensitive-note section-space">Solo tú tienes acceso a la información de tu negocio.</p></section></main>`;}
function parseRoute(){const parts=location.hash.slice(1).split('/');route=parts[0]||'home';recordId=parts[1]||'';mode=parts[2]||'';if(recordId==='new'){recordId='';mode='edit';}search='';filter='';}
function quickNotes(){return Object.values(state.records).filter(r=>r.kind==='resources'&&r.recordType==='quick-note'&&!r.archived).sort((a,b)=>Number(Boolean(b.pinned))-Number(Boolean(a.pinned))||String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')));}
function noteTime(value){if(!value)return '';const date=new Date(value);return Number.isNaN(+date)?'':new Intl.DateTimeFormat('es-DO',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Santo_Domingo'}).format(date);}
function noteRelationValue(note){return note?.relatedKind&&note?.relatedId?`${note.relatedKind}:${note.relatedId}`:'';}
function noteRelationLabel(note){const record=note?.relatedId&&state.records[note.relatedId];if(!record)return '';return `${({clients:'Cliente',orders:'Pedido',quotes:'Cotización',content:'Contenido'})[note.relatedKind]||'Registro'} · ${record.number||record.name}`;}
function noteRelationOptions(selected=''){const groups=[['clients','Clientes'],['orders','Pedidos'],['quotes','Cotizaciones'],['content','Contenido']];return `<option value="">Sin vincular</option>${groups.map(([kind,label])=>{const rows=list(state,kind).sort((a,b)=>String(a.number||a.name).localeCompare(String(b.number||b.name),'es'));return rows.length?`<optgroup label="${label}">${rows.map(r=>`<option value="${kind}:${esc(r.id)}" ${selected===`${kind}:${r.id}`?'selected':''}>${esc(r.number||r.name)}</option>`).join('')}</optgroup>`:'';}).join('')}`;}
function visibleQuickNotes(){let notes=quickNotes();const query=noteQuery.trim().toLocaleLowerCase('es');if(query)notes=notes.filter(n=>[n.title,n.name,n.note,noteRelationLabel(n)].some(value=>String(value||'').toLocaleLowerCase('es').includes(query)));if(noteFilter==='pinned')notes=notes.filter(n=>n.pinned);if(noteFilter==='recent')notes=notes.sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||''))).slice(0,10);return notes;}
function quickNoteCard(note){const relation=noteRelationLabel(note),task=note.taskId&&state.records[note.taskId];return `<article class="quick-note-card"><div class="quick-note-card-head"><div><h3>${esc(note.title||note.name||'Nota')}</h3>${note.pinned?`<span class="note-pinned" title="Nota fijada" aria-label="Nota fijada">${icon('pin')}</span>`:''}</div><details class="quick-note-menu"><summary aria-label="Opciones de ${esc(note.title||note.name||'nota')}">⋮</summary><div><button type="button" data-action="edit-note" data-id="${esc(note.id)}">Editar</button><button type="button" data-action="toggle-note-pin" data-id="${esc(note.id)}">${note.pinned?'Desfijar':'Fijar'}</button>${task?`<a href="#tasks/${esc(task.id)}">Ver tarea</a>`:`<button type="button" data-action="note-to-task" data-id="${esc(note.id)}">Convertir en tarea</button>`}<button type="button" class="danger" data-action="delete-note" data-id="${esc(note.id)}">Eliminar</button></div></details></div><p>${esc(note.note)}</p><div class="quick-note-meta">${relation?`<a href="#${esc(note.relatedKind)}/${esc(note.relatedId)}">${icon('link')}<span>${esc(relation)}</span></a>`:''}${note.reminderDate?`<span>${icon('bell')}<time datetime="${esc(note.reminderDate)}">${esc(new Intl.DateTimeFormat('es-DO',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(note.reminderDate+'T12:00:00Z')))}</time></span>`:''}${task?`<a href="#tasks/${esc(task.id)}">Tarea creada</a>`:''}<time datetime="${esc(note.updatedAt||note.createdAt||'')}">${esc(noteTime(note.updatedAt||note.createdAt))}</time></div></article>`;}
function quickNotesResults(){const notes=visibleQuickNotes();return notes.length?notes.map(quickNoteCard).join(''):`<p class="quick-notes-empty">${noteQuery?'No hay notas que coincidan con la búsqueda.':noteFilter==='pinned'?'Todavía no tienes notas fijadas.':'Todavía no has guardado notas.'}</p>`;}
function quickNotesPanel(){const editing=editingNoteId&&state.records[editingNoteId]?.recordType==='quick-note'?state.records[editingNoteId]:null,mobile=window.matchMedia('(max-width:540px)').matches;return `<aside class="quick-notes-panel${notesOpen?' open':''}" id="quick-notes-panel" role="dialog" aria-modal="${notesOpen&&mobile?'true':'false'}" aria-labelledby="quick-notes-title" aria-hidden="${notesOpen?'false':'true'}"><div class="quick-notes-head"><div><h2 id="quick-notes-title">Notas</h2><p>Ideas, apuntes de reuniones y recordatorios breves.</p></div><button type="button" data-action="notes-close" aria-label="Cerrar notas">×</button></div><div class="quick-notes-scroll"><form id="quick-note-form" data-id="${esc(editing?.id||'')}"><h3>${editing?'Editar nota':'Nueva nota'}</h3><label class="field"><span>Título (opcional)</span><input name="title" value="${esc(editing?.title||'')}" maxlength="80" placeholder="Ej. Materiales para pedido"></label><label class="field"><span>Nota</span><textarea id="quick-note-text" name="note" rows="3" placeholder="Escribe una nota…" required>${esc(editing?.note||'')}</textarea></label><div class="quick-note-options"><label class="field"><span>Vincular con</span><select name="relation">${noteRelationOptions(noteRelationValue(editing))}</select></label><label class="field"><span>Recordatorio</span><input type="date" name="reminderDate" value="${esc(editing?.reminderDate||'')}"></label></div><label class="quick-note-pin"><input type="checkbox" name="pinned" ${editing?.pinned?'checked':''}><span>Fijar como importante</span></label><div class="quick-note-actions">${editing?'<button type="button" data-action="cancel-note-edit">Cancelar</button>':''}<button class="notes-save" type="submit">${editing?'Guardar cambios':'Guardar nota'}</button></div></form><section class="quick-notes-list" aria-label="Notas guardadas"><label class="quick-note-search">${icon('search')}<input id="quick-note-search" type="search" value="${esc(noteQuery)}" placeholder="Buscar en notas…" aria-label="Buscar en notas"></label><div class="quick-note-filters" role="group" aria-label="Filtrar notas">${[['all','Todas'],['pinned','Fijadas'],['recent','Recientes']].map(([value,label])=>`<button type="button" data-action="note-filter" data-filter="${value}" class="${noteFilter===value?'active':''}" aria-pressed="${noteFilter===value}">${label}</button>`).join('')}</div><div id="quick-note-results">${quickNotesResults()}</div></section></div></aside>`;}
function captureNoteDraft(){const form=$('#quick-note-form'),scroll=$('.quick-notes-scroll');if(!form)return null;const fd=new FormData(form);return {id:form.dataset.id||'',title:String(fd.get('title')||''),note:String(fd.get('note')||''),relation:String(fd.get('relation')||''),reminderDate:String(fd.get('reminderDate')||''),pinned:fd.has('pinned'),scrollTop:scroll?.scrollTop||0};}
function restoreNoteDraft(draft){if(!draft)return;const form=$('#quick-note-form');if(!form||form.dataset.id!==(draft.id||''))return;form.elements.title.value=draft.title;form.elements.note.value=draft.note;form.elements.relation.value=draft.relation;form.elements.reminderDate.value=draft.reminderDate;form.elements.pinned.checked=draft.pinned;const scroll=$('.quick-notes-scroll');if(scroll)scroll.scrollTop=draft.scrollTop;}
function refreshQuickNotesList(){document.querySelectorAll('[data-action="note-filter"]').forEach(button=>{const active=button.dataset.filter===noteFilter;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});const results=$('#quick-note-results');if(results)results.innerHTML=quickNotesResults();}
function syncNotesPanelState(focus=false){const panel=$('#quick-notes-panel'),mobile=window.matchMedia('(max-width:540px)').matches,shell=$('.shell');if(!panel)return;panel.classList.toggle('open',notesOpen);panel.setAttribute('aria-hidden',String(!notesOpen));panel.setAttribute('aria-modal',String(notesOpen&&mobile));if(shell)shell.inert=Boolean(notesOpen&&mobile);if(focus&&notesOpen)panel.querySelector(editingNoteId?'[name=title]':'#quick-note-text')?.focus();}
