function revealActiveTab(){requestAnimationFrame(()=>{const selected=$('.tabs .active'),bar=selected?.parentElement;if(!bar||bar.scrollWidth<=bar.clientWidth)return;const item=selected.getBoundingClientRect(),bounds=bar.getBoundingClientRect();if(item.left<bounds.left)bar.scrollLeft-=bounds.left-item.left+18;if(item.right>bounds.right)bar.scrollLeft+=item.right-bounds.right+18;});}
function ownerName(){return 'Melani';}
