function currentViewControl(){const options=viewOptions[route]||[[route,pageTitle]],current=options.find(([value])=>value===route)||options[0];return `<div class="current-view-control"><span>Vista actual</span>${options.length>1?`<select class="hub-view-select" aria-label="Vista actual">${options.map(([value,label])=>`<option value="${value}" ${value===route?'selected':''}>${label}</option>`).join('')}</select>`:`<strong>${esc(current[1])}</strong>`}</div>`;}
function homeHeader(){const name=ownerName();return `<header class="home-header"><button class="menu-toggle" data-action="menu" aria-label="Abrir menú" aria-controls="sidebar" aria-expanded="false">${icon('menu')}</button><div class="home-welcome"><span>LIFE DECO ART HUB</span><h1>Buenos días, <strong>${esc(name)}</strong></h1><p>Esto es lo que necesita tu atención hoy.</p></div><div class="view-header-controls">${currentViewControl()}${notesButton()}</div></header>`;}
