function salesHeader(){const creating=mode==='edit'&&!recordId,label=route==='quotes'?'Cotizaciones':'Facturas';return `<header class="home-header section-action-header sales-header"><button class="menu-toggle" data-action="menu" aria-label="Abrir menú" aria-controls="sidebar" aria-expanded="false">${icon('menu')}</button><div class="home-welcome"><h1>${esc(pageTitle)}</h1>${creating?`<a class="sales-back" href="#${route}">← Volver a ${label.toLowerCase()}</a>`:`<p>${esc(pageDescription)}</p>`}</div><div class="view-header-controls">${currentViewControl()}${notesButton()}</div></header>`;}
function shell(content){const active=nav.find(([, , ,routes])=>routes.includes(route))?.[0]||'home',isHome=route==='home',isClients=route==='clients'&&!recordId&&mode!=='edit',isSalesRoute=['quotes','invoices'].includes(route),isSalesEditor=isSalesRoute&&mode==='edit',isList=!recordId&&mode!=='edit',headerActions=isList?`<div class="view-header-controls">${currentViewControl()}${notesButton()}</div>`:`<div class="actions">${pageActions}</div>`,header=isHome?homeHeader():isSalesRoute?salesHeader():isClients?sectionHeader():`<header class="page-header"><div class="topbar"><button class="menu-toggle" data-action="menu" aria-label="Abrir menú" aria-controls="sidebar" aria-expanded="false">${icon('menu')}</button><div class="topbar-copy"><h1>${esc(pageTitle)}</h1><p>${esc(pageDescription)}</p></div>${headerActions}</div>${pageTabs}</header>`;$('#app').innerHTML=`<div class="shell home-shell"><aside class="sidebar" id="sidebar"><button type="button" class="mobile-close" data-action="menu-close">Cerrar menú</button><a class="brand" href="#home"><span class="brand-name">LIFE DECO ART</span><span class="brand-context">HUB — Gestión</span></a><nav aria-label="Menú principal">${nav.map(([key,label,i])=>`<a href="#${key}" ${active===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('')}</nav><div class="sidebar-footer"><button type="button" data-action="logout">Cerrar sesión</button></div></aside><div class="workspace home-workspace">${header}<main id="main" class="main${isHome||isClients||isSalesRoute?' home-main':''}${isClients?' clients-main':''}${isSalesRoute?' sales-main':''}${isSalesEditor?' sales-editor-main':''}" tabindex="-1">${content}</main></div></div>${quickNotesPanel()}${isClients?clientPanel():''}${createPanelKind?createPanel():''}`;revealActiveTab();hydrateImages();syncNotesPanelState();syncClientPanelState();}
const head=(title,description='',actions='')=>{pageTitle=title;pageDescription=description||schemas[route]?.description||'Tu espacio de trabajo.';pageActions=actions;pageTabs='';return '';};
function empty(kind){return `<div class="empty">${icon(kind==='clients'?'people':'doc')}<h2>Todavía no hay ${esc(schemas[kind]?.title.toLowerCase()||'registros')}</h2><p>Empieza con tu primer registro. Aquí podrás encontrarlo y darle seguimiento.</p></div>`;}
