const salesStatusLabel=status=>({aprobada:'Aceptada',pendiente:'Emitida',anulada:'Cancelada'}[status]||status.charAt(0).toUpperCase()+status.slice(1));
function salesStatus(record){if(record.kind==='invoices'){const current=documentStatus(state,record);if(current==='pendiente'&&paid(state,record.id)>0)return 'pago parcial';return current;}return documentStatus(state,record);}
function salesRows(){const query=search.trim().toLocaleLowerCase('es'),month=today().slice(0,7);let rows=list(state,route,true).filter(r=>!r.archived);if(query)rows=rows.filter(r=>[r.number,r.name,state.records[r.clientId]?.name].some(value=>String(value||'').toLocaleLowerCase('es').includes(query)));if(filter)rows=rows.filter(r=>salesStatus(r)===filter);if(salesDate==='month')rows=rows.filter(r=>String(r.date||r.createdAt||'').slice(0,7)===month);if(salesDate==='30'){const limit=new Date();limit.setDate(limit.getDate()-30);rows=rows.filter(r=>new Date(`${r.date||String(r.createdAt||'').slice(0,10)}T12:00:00`)>=limit);}return rows.sort((a,b)=>salesSort==='amount'?totals(b).total-totals(a).total:salesSort==='client'?String(state.records[a.clientId]?.name||'').localeCompare(String(state.records[b.clientId]?.name||''),'es'):String(b.date||b.updatedAt||b.createdAt||'').localeCompare(String(a.date||a.updatedAt||a.createdAt||'')));}
function salesMetrics(){const rows=list(state,route,true).filter(r=>!r.archived),month=today().slice(0,7);let values;if(route==='quotes'){const active=rows.filter(r=>!['rechazada','cancelada'].includes(salesStatus(r))),pending=rows.filter(r=>salesStatus(r)==='enviada'),quoted=active.reduce((sum,r)=>sum+totals(r).total,0),week=new Date(`${today()}T12:00:00Z`);week.setUTCDate(week.getUTCDate()+7);const limit=week.toISOString().slice(0,10),due=active.filter(r=>r.validUntil&&r.validUntil>=today()&&r.validUntil<=limit).length;values=[['doc','Cotizaciones activas',active.length,'En seguimiento',false],['clock','Pendientes de respuesta',pending.length,'Requieren atención',false],['money','Valor cotizado',quoted,'Total activo',true],['calendar','Por vencer',due,'Próximos 7 días',false]];}else{const issued=rows.filter(r=>r.status!=='borrador'&&String(r.date||r.issuedAt||'').slice(0,7)===month),receivable=rows.filter(r=>!['borrador','anulada'].includes(r.status)).reduce((sum,r)=>sum+balance(state,r),0),overdue=rows.filter(r=>salesStatus(r)==='vencida').length,collected=list(state,'payments',true).filter(p=>p.type!=='refund'&&String(p.date||'').slice(0,7)===month&&rows.some(r=>r.id===p.target)).reduce((sum,p)=>sum+Number(p.amount||0),0);values=[['doc','Facturas emitidas',issued.length,'Este mes',false],['clock','Por cobrar',receivable,'Saldo pendiente',true],['money','Vencidas',overdue,'Requieren atención',false],['calendar','Cobrado este mes',collected,'Pagos registrados',true]];}return values.map(([i,t,v,d,currency])=>`<article class="sales-metric"><span>${icon(i)}</span><div><small>${t}</small><strong>${currency?money(v):v}</strong><p>${d}</p></div></article>`).join('');}
function salesDateLabel(value){if(!value)return 'Sin fecha';const date=new Date(`${value}T12:00:00Z`);return Number.isNaN(+date)?esc(value):new Intl.DateTimeFormat('es-DO',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(date);}
function salesTable(){const rows=salesRows(),filtered=search||filter||salesDate!=='all',quote=route==='quotes';if(!rows.length)return `<div class="sales-empty"><h2>${filtered?'No hay resultados con estos filtros.':quote?'Todavía no hay cotizaciones':'Todavía no hay facturas'}</h2><p>${filtered?'Prueba otra búsqueda o cambia los filtros.':quote?'Las propuestas que prepares aparecerán aquí.':'Las facturas que emitas aparecerán aquí.'}</p></div>`;return `<div class="sales-table-wrap"><table class="sales-table"><thead><tr>${quote?'<th>Cotización</th><th>Cliente</th><th>Proyecto / pedido</th><th>Total</th><th>Emitida</th><th>Válida hasta</th><th>Estado</th>':'<th>Factura</th><th>Cliente</th><th>Proyecto / pedido</th><th>Total</th><th>Pagado</th><th>Saldo</th><th>Vencimiento</th><th>Estado</th>'}<th aria-label="Abrir"></th></tr></thead><tbody>${rows.map(r=>`<tr><td><a href="#${route}/${r.id}">${esc(r.number)}</a></td><td>${esc(state.records[r.clientId]?.name||'Sin cliente')}</td><td>${esc(r.name||'Sin nombre')}</td><td class="num">${money(totals(r).total)}</td>${quote?`<td>${salesDateLabel(r.date)}</td><td>${salesDateLabel(r.validUntil)}</td>`:`<td class="num">${money(paid(state,r.id))}</td><td class="num">${money(balance(state,r))}</td><td>${salesDateLabel(r.due)}</td>`}<td><span class="sales-status">${esc(salesStatusLabel(salesStatus(r)))}</span></td><td><a class="sales-row-open" href="#${route}/${r.id}" aria-label="Abrir ${esc(r.number)}">›</a></td></tr>`).join('')}</tbody></table></div>`;}
function salesPage(){head('Ventas','Gestiona cotizaciones, facturas y el avance de cada venta.');const states=route==='quotes'?[['','Todos los estados'],['borrador','Borradores'],['enviada','Enviadas'],['aprobada','Aprobadas'],['rechazada','Rechazadas'],['vencida','Vencidas'],['cancelada','Canceladas']]:[['','Todos los estados'],['borrador','Borradores'],['pendiente','Pendientes'],['pago parcial','Pago parcial'],['pagada','Pagadas'],['vencida','Vencidas'],['anulada','Anuladas']];return `<section class="sales-metrics">${salesMetrics()}</section><section class="sales-panel"><div class="sales-toolbar"><label class="sales-search">${icon('search')}<input id="sales-search" type="search" value="${esc(search)}" placeholder="Buscar por número, cliente o proyecto" aria-label="Buscar en ventas"></label><select id="sales-status" aria-label="Filtrar por estado">${states.map(([value,label])=>`<option value="${value}" ${filter===value?'selected':''}>${label}</option>`).join('')}</select><select id="sales-date" aria-label="Filtrar por fecha"><option value="all">Todas las fechas</option><option value="month" ${salesDate==='month'?'selected':''}>Este mes</option><option value="30" ${salesDate==='30'?'selected':''}>Últimos 30 días</option></select><button type="button" class="sales-export-button" data-action="sales-csv">Exportar CSV</button><button type="button" class="sales-create-button" data-action="create-record" data-kind="${route}">${icon('plus')}<span>Nueva ${route==='quotes'?'cotización':'factura'}</span></button></div><div id="sales-results">${salesTable()}</div></section>`;}
function dataTable(kind,rows){return `<div class="table-wrap"><table><thead><tr><th>${['quotes','invoices','orders'].includes(kind)?'Documento':'Nombre'}</th><th>Detalle</th><th>Estado</th><th>Importe / fecha</th></tr></thead><tbody>${rows.map(r=>{
 let detail=r.category||r.email||r.channel||r.supplier||r.type||'',last=r.date||r.renewal||'';
 if(['quotes','invoices','orders'].includes(kind)){detail=state.records[r.clientId]?.name||r.client?.name||'';last=money(totals(r).total);}if(kind==='calculations'){const c=calculate(r);detail=`${c.units} unidades · ${c.margin.toFixed(1)} % margen`;last=money(c.sale);}if(kind==='materials'){detail=r.track?`${stock(state,r.id)} ${r.unit||'unidades'} disponibles`:'Sin control de existencias';last=money(cents(r.unitCost));}if(kind==='purchases')last=money(cents(r.total));if(kind==='expenses')last=money(cents(r.amount));if(kind==='products')last=r.pricing==='por cotizar'?'Por cotizar':money(cents(r.price));
 return `<tr><td>${link(kind,r)}${r.number?`<br><small>${esc(r.name)}${r.revision>1?' · v'+r.revision:''}</small>`:''}</td><td>${esc(detail)}</td><td>${badge(r.archived?'archivado':documentStatus(state,r))}</td><td class="num">${esc(last)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function listPage(){const schema=schemas[route];if(!schema)return head('Página no encontrada')+'<a href="#home">Volver al inicio</a>';const rows=list(state,route,true).filter(r=>r.recordType!=='quick-note');return head(schema.title,schema.description)+tabs()+`<section class="list-panel"><div class="toolbar"><label class="sr-search"><input id="search" type="search" placeholder="Buscar en ${esc(schema.title.toLowerCase())}" aria-label="Buscar registros"></label><select id="filter" aria-label="Filtrar registros"><option value="">Activos</option><option value="all">Todos, incluidos archivados</option><option value="archived">Archivados</option>${[...new Set(rows.map(r=>documentStatus(state,r)))].sort().map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select>${['orders','content','tasks'].includes(route)?btn(listMode==='board'?'Ver lista':'Ver tablero','toggle-board'):''}${route==='tasks'?btn('Ver calendario','calendar'):''}${btn('Exportar CSV','csv')}${btn('Nuevo '+schema.singular,'new',`data-kind="${route}"`)}</div><div id="list-results">${listResults()}</div></section>`;}
function filtered(){return list(state,route,true).filter(r=>r.recordType!=='quick-note').filter(r=>filter==='all'||(filter==='archived'?r.archived:!r.archived&&(!filter||documentStatus(state,r)===filter))).filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));}
function listResults(){const rows=filtered();if(!rows.length)return search||filter?'<div class="sheet empty"><p>No hay resultados con estos filtros.</p></div>':`<div class="sheet">${empty(route)}</div>`;if(route==='resources')return `<div class="resource-grid">${rows.map(r=>`<article class="resource-card"><div class="resource-image">${r.path&&r.mime?.startsWith('image/')?`<img data-resource="${r.id}" alt="${esc(r.name)}">`:icon('image')}</div><div class="resource-body">${link(route,r)}<p>${esc(r.category||r.role||'Recurso')}</p>${badge(r.visibility||'interno')}</div></article>`).join('')}</div>`;if(listMode==='board'&&['orders','content','tasks'].includes(route)){const states=route==='orders'?['pendiente','en diseño','esperando aprobación','en producción','listo para entregar','entregado','cancelado']:route==='content'?['idea','en preparación','listo','programado','publicado']:['pendiente','en curso','completada','cancelada'];return `<div class="board">${states.map(status=>`<section class="board-col"><h2>${esc(status)} · ${rows.filter(r=>r.status===status).length}</h2>${rows.filter(r=>r.status===status).map(r=>`<a class="board-item" href="#${route}/${r.id}">${esc(r.name)}<small>${esc(r.number||r.date||r.due||'')}</small></a>`).join('')}</section>`).join('')}</div>`;}return `<div class="sheet">${dataTable(route,rows)}</div>`;}

function clientOrders(clientId){return list(state,'orders',true).filter(order=>order.clientId===clientId);}
function clientInvoices(clientId){return list(state,'invoices',true).filter(invoice=>invoice.clientId===clientId&&!['borrador','anulada'].includes(invoice.status));}
function clientBalance(clientId){return clientInvoices(clientId).reduce((sum,invoice)=>sum+Math.max(0,balance(state,invoice.id)),0);}
function clientInitials(client){return String(client.name||client.companyName||'C').split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase();}
function clientDate(value){if(!value)return 'Sin actividad';const date=new Date(value);if(Number.isNaN(+date))return '';const days=Math.max(0,Math.floor((new Date()-date)/86400000));if(days===0)return 'Hoy';if(days===1)return 'Hace 1 día';if(days<30)return `Hace ${days} días`;return new Intl.DateTimeFormat('es-DO',{day:'numeric',month:'short',year:'numeric'}).format(date);}
function visibleClients(){let rows=list(state,'clients').filter(client=>!client.archived),query=search.trim().toLocaleLowerCase('es');if(query)rows=rows.filter(client=>[client.name,client.companyName,client.contactName,client.phone,client.email,client.instagram,client.tags].some(value=>String(value||'').toLocaleLowerCase('es').includes(query)));if(clientTypeFilter!=='all')rows=rows.filter(client=>(client.clientType||'person')===clientTypeFilter);if(clientTagFilter)rows=rows.filter(client=>String(client.tags||'').split(',').map(tag=>tag.trim().toLocaleLowerCase('es')).includes(clientTagFilter.toLocaleLowerCase('es')));return rows.sort((a,b)=>clientSort==='name'?String(a.name).localeCompare(String(b.name),'es'):clientSort==='balance'?clientBalance(b.id)-clientBalance(a.id):String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')));}
function clientsResults(){const rows=visibleClients();if(!rows.length)return `<div class="clients-empty"><h2>${search||clientTypeFilter!=='all'||clientTagFilter?'No hay clientes con estos filtros.':'Todavía no hay clientes.'}</h2><p>${search||clientTypeFilter!=='all'||clientTagFilter?'Prueba otra búsqueda o cambia los filtros.':'Crea el primer cliente para comenzar a organizar su información y sus pedidos.'}</p></div>`;return `<div class="clients-table-wrap"><table class="clients-table"><thead><tr><th>Cliente</th><th>Contacto</th><th>Último pedido</th><th>Pedidos activos</th><th>Saldo</th><th>Última actividad</th><th>Acción</th></tr></thead><tbody>${rows.map(client=>{const orders=clientOrders(client.id).sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||''))),last=orders[0],active=orders.filter(order=>!['entregado','cancelado'].includes(order.status)).length;return `<tr><td><div class="client-identity"><span class="client-avatar">${esc(clientInitials(client))}</span><div><a href="#clients/${esc(client.id)}">${esc(client.name)}</a><small>${esc(client.clientType==='company'?'Empresa':client.tags||'Cliente')}</small></div></div></td><td><span>${esc(client.phone||'Sin teléfono')}</span><small>${esc(client.email||client.instagram||'Sin correo')}</small></td><td>${last?`<a href="#orders/${esc(last.id)}">${esc(last.name||last.number)}</a><small>${esc(clientDate(last.createdAt))}</small>`:'<span class="muted">Sin pedidos</span>'}</td><td class="num">${active}</td><td class="num">${money(clientBalance(client.id))}</td><td>${esc(clientDate(client.updatedAt||client.createdAt))}</td><td><div class="client-row-actions"><a class="client-open" href="#clients/${esc(client.id)}">Abrir</a><span aria-hidden="true">⋮</span></div></td></tr>`;}).join('')}</tbody></table></div><div class="clients-count">Mostrando ${rows.length} de ${list(state,'clients').filter(client=>!client.archived).length} clientes</div>`;}
function clientsPage(){const clients=list(state,'clients').filter(client=>!client.archived),month=today().slice(0,7),active=clients.filter(client=>clientOrders(client.id).some(order=>!['entregado','cancelado'].includes(order.status))).length,pending=clients.filter(client=>clientBalance(client.id)>0).length,newCount=clients.filter(client=>String(client.createdAt||'').slice(0,7)===month).length,tags=[...new Set(clients.flatMap(client=>String(client.tags||'').split(',').map(tag=>tag.trim()).filter(Boolean)))].sort((a,b)=>a.localeCompare(b,'es'));head('Clientes','Organiza la información, pedidos e historial de cada cliente.');return `<div class="client-metrics"><article class="client-metric"><span>${icon('people')}</span><div><small>Total de clientes</small><strong>${clients.length}</strong><p>Personas y empresas</p></div></article><article class="client-metric"><span>${icon('doc')}</span><div><small>Con pedidos activos</small><strong>${active}</strong><p>Pedidos en proceso</p></div></article><article class="client-metric"><span>${icon('clock')}</span><div><small>Con saldo pendiente</small><strong>${pending}</strong><p>Pagos pendientes</p></div></article><article class="client-metric"><span>${icon('plus')}</span><div><small>Nuevos este mes</small><strong>${newCount}</strong><p>Registrados este mes</p></div></article></div><section class="clients-list-panel"><div class="clients-toolbar"><label class="clients-search">${icon('search')}<input id="client-search" type="search" value="${esc(search)}" placeholder="Buscar por nombre, teléfono, correo o empresa" aria-label="Buscar clientes"></label><select id="client-type-filter" aria-label="Filtrar por tipo"><option value="all">Todos los clientes</option><option value="person" ${clientTypeFilter==='person'?'selected':''}>Personas</option><option value="company" ${clientTypeFilter==='company'?'selected':''}>Empresas</option></select><select id="client-tag-filter" aria-label="Filtrar por etiqueta"><option value="">Etiquetas</option>${tags.map(tag=>`<option value="${esc(tag)}" ${clientTagFilter===tag?'selected':''}>${esc(tag)}</option>`).join('')}</select><select id="client-sort" aria-label="Ordenar clientes"><option value="recent">Actividad reciente</option><option value="name" ${clientSort==='name'?'selected':''}>Nombre</option><option value="balance" ${clientSort==='balance'?'selected':''}>Mayor saldo</option></select><button type="button" data-action="csv" aria-label="Exportar clientes en CSV">Exportar CSV</button><button type="button" class="client-create-button" data-action="create-record" data-kind="clients">${icon('plus')}<span>Nuevo cliente</span></button></div><div id="client-results">${clientsResults()}</div></section>`;}
function clientExtraFields(){return `<details class="client-more"><summary>Más información <span>${icon('chevron')}</span></summary><p>Preferencias, origen, etiquetas y dirección.</p><section><h3>Relación comercial</h3><div class="client-form-grid"><label class="field"><span>¿Cómo conoció Life Deco Art?</span><input name="source"></label><label class="field"><span>Canal preferido</span><select name="preferredChannel"><option value="">Sin preferencia</option><option>WhatsApp</option><option>Llamada</option><option>Correo</option><option>Instagram</option></select></label><fieldset class="client-interests"><legend>Intereses</legend>${['Lettering','Decoración','Regalos','Eventos','Corporativo','Otros'].map(value=>`<label><input type="checkbox" name="interests" value="${value}"><span>${value}</span></label>`).join('')}</fieldset><label class="field wide"><span>Etiquetas</span><input name="tags" placeholder="Ej. Frecuente, corporativo"></label><label class="field wide"><span>Observaciones</span><textarea name="observations" rows="3"></textarea></label></div></section><section><h3>Entrega y facturación</h3><div class="client-form-grid"><label class="field"><span>Cédula o RNC</span><input name="identityNumber"></label><label class="field"><span>Preferencia de entrega</span><select name="deliveryPreference"><option value="">Sin preferencia</option><option>Recoger</option><option>Entrega local</option><option>Envío</option></select></label><label class="field wide"><span>Dirección</span><input name="address"></label><label class="field"><span>Sector</span><input name="sector"></label><label class="field"><span>Ciudad o provincia</span><input name="city"></label><label class="field wide"><span>Referencia para la entrega</span><textarea name="deliveryReference" rows="2"></textarea></label></div></section></details>`;}
function clientPanel(){const mobile=window.matchMedia('(max-width:640px)').matches;return `<div class="client-panel-layer${clientPanelOpen?' open':''}" aria-hidden="${clientPanelOpen?'false':'true'}"><button type="button" class="client-panel-backdrop" data-action="client-cancel" aria-label="Cerrar formulario de cliente"></button><aside class="client-panel" id="client-panel" role="dialog" aria-modal="${clientPanelOpen&&mobile?'true':'false'}" aria-labelledby="client-panel-title"><form id="client-form"><header><div><h2 id="client-panel-title">Nuevo cliente</h2><p>Registra la información esencial. Podrás completar el perfil después.</p></div><button type="button" data-action="client-cancel" aria-label="Cerrar formulario">×</button></header><div class="client-panel-scroll"><div class="client-type-switch" role="group" aria-label="Tipo de cliente"><button type="button" data-action="client-type" data-type="person" class="${clientType==='person'?'active':''}" aria-pressed="${clientType==='person'}">${icon('people')} Persona</button><button type="button" data-action="client-type" data-type="company" class="${clientType==='company'?'active':''}" aria-pressed="${clientType==='company'}">${icon('catalog')} Empresa</button></div><input type="hidden" name="clientType" value="${clientType}"><section class="client-essential"><h3>Información esencial</h3><div class="client-form-grid client-person-fields" ${clientType==='person'?'':'hidden'}><label class="field wide"><span>Nombre completo *</span><input name="personName" placeholder="Ej. Laura Méndez" ${clientType==='person'?'required':''}></label><label class="field"><span>Teléfono o WhatsApp</span><input name="personPhone" inputmode="tel" placeholder="Ej. (809) 555-0192"></label><label class="field"><span>Correo electrónico</span><input name="personEmail" type="email" placeholder="Ej. laura@gmail.com"></label><label class="field wide"><span>Instagram (opcional)</span><div class="input-prefix"><span>@</span><input name="instagram" placeholder="lauramendez"></div></label></div><div class="client-form-grid client-company-fields" ${clientType==='company'?'':'hidden'}><label class="field wide"><span>Nombre de la empresa *</span><input name="companyName" placeholder="Ej. Estudio Brisa" ${clientType==='company'?'required':''}></label><label class="field"><span>Persona de contacto</span><input name="contactName"></label><label class="field"><span>Cargo (opcional)</span><input name="role"></label><label class="field"><span>Teléfono o WhatsApp</span><input name="companyPhone" inputmode="tel"></label><label class="field"><span>Correo empresarial</span><input name="companyEmail" type="email"></label><label class="field wide"><span>RNC (opcional)</span><input name="rnc"></label></div><div id="client-duplicate-warning" class="client-duplicate-warning" hidden></div><div id="client-form-error" role="alert"></div></section>${clientExtraFields()}</div><footer><p>Solo necesitas un nombre y un medio de contacto.</p><div><button type="button" data-action="client-cancel">Cancelar</button><button type="submit" name="intent" value="save">Guardar cliente</button><button type="submit" name="intent" value="order" class="client-order-button">Guardar y crear pedido</button></div></footer></form></aside></div>`;}
function syncClientPanelState(focus=false){const layer=$('.client-panel-layer');if(!layer)return;layer.classList.toggle('open',clientPanelOpen);layer.setAttribute('aria-hidden',String(!clientPanelOpen));if(focus&&clientPanelOpen)$('#client-form input:not([type=hidden])')?.focus();}
function setClientType(type){clientType=type==='company'?'company':'person';const form=$('#client-form');if(!form)return;form.elements.clientType.value=clientType;form.querySelector('.client-person-fields').hidden=clientType!=='person';form.querySelector('.client-company-fields').hidden=clientType!=='company';form.elements.personName.required=clientType==='person';form.elements.companyName.required=clientType==='company';form.querySelectorAll('[data-action="client-type"]').forEach(button=>{const active=button.dataset.type===clientType;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});clientDuplicateOverride=false;refreshClientDuplicate();}
function clientDuplicateFromForm(){const form=$('#client-form');if(!form)return null;const phone=String(form.elements[clientType==='company'?'companyPhone':'personPhone'].value||'').replace(/\D/g,''),email=String(form.elements[clientType==='company'?'companyEmail':'personEmail'].value||'').trim().toLocaleLowerCase('es');if(!phone&&!email)return null;return list(state,'clients',true).find(client=>(phone&&String(client.phone||'').replace(/\D/g,'')===phone)||(email&&String(client.email||'').trim().toLocaleLowerCase('es')===email))||null;}
function refreshClientDuplicate(){const warning=$('#client-duplicate-warning'),duplicate=clientDuplicateFromForm();if(!warning)return;warning.hidden=!duplicate||clientDuplicateOverride;if(!warning.hidden){const form=$('#client-form'),phone=String(form.elements[clientType==='company'?'companyPhone':'personPhone'].value||'').replace(/\D/g,'');warning.innerHTML=`<div>${icon('clock')}<p><strong>Ya existe un cliente con este ${phone?'teléfono':'correo'}.</strong><span>${esc(duplicate.name)}</span></p></div><div><button type="button" data-action="client-duplicate-open" data-id="${esc(duplicate.id)}">Abrir cliente existente</button><button type="button" data-action="client-duplicate-continue">Continuar de todos modos</button></div>`;}}
function agendaRows(rows){return rows.length?rows.map(r=>`<div class="agenda-row"><div>${link(r.kind,r)}<small>${esc(r.priority||schemas[r.kind]?.title||'')}</small></div><span class="num">${esc(r.eventDate||r.due||'Sin fecha')}</span></div>`).join(''):'<p class="muted">No hay fechas pendientes.</p>';}
function monthWindow(offset=0){const current=new Date(`${today()}T12:00:00Z`);current.setUTCDate(1);current.setUTCMonth(current.getUTCMonth()+offset);const from=current.toISOString().slice(0,10),end=new Date(current);end.setUTCMonth(end.getUTCMonth()+1);end.setUTCDate(0);return [from,end.toISOString().slice(0,10)];}
function upcomingDateLabel(value,current){if(value===current)return 'Hoy';const next=new Date(`${current}T12:00:00Z`);next.setUTCDate(next.getUTCDate()+1);if(value===next.toISOString().slice(0,10))return 'Mañana';return new Intl.DateTimeFormat('es-DO',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(`${value}T12:00:00Z`));}
function upcomingEventRow(r,date){const content=`<time datetime="${esc(r.eventDate)}">${esc(upcomingDateLabel(r.eventDate,date))}</time><div><strong>${esc(r.name)}</strong><small>${esc(r.time||r.description||r.note||r.priority||schemas[r.kind]?.title||'Compromiso programado')}</small></div>`;return r.kind==='resources'&&r.recordType==='quick-note'?`<button type="button" class="today-row" data-action="open-note" data-id="${esc(r.id)}">${content}</button>`:`<a class="today-row" href="#${r.kind}/${r.id}">${content}</a>`;}
function invoiceSales(from,to){return list(state,'invoices',true).filter(r=>!['borrador','anulada'].includes(r.status)).filter(r=>{const date=(r.issuedAt||r.date||'').slice(0,10);return date>=from&&date<=to;}).reduce((sum,r)=>sum+totals(r).total,0);}
function trend(current,previous){if(!previous)return current?'<span class="trend neutral">Sin comparación anterior</span>':'<span class="trend neutral">Sin cambios este mes</span>';const value=Math.round((current-previous)/previous*100),up=value>=0;return `<span class="trend ${up?'up':'down'}">${up?'↗':'↘'} ${value>0?'+':''}${value}% <small>vs. mes anterior</small></span>`;}
function dashboardTitle(title,copy='',href='',linkLabel='Ver todo'){return `<div class="dashboard-title"><div class="dashboard-heading"><div><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}</div></div>${href?`<a href="${href}">${linkLabel}</a>`:''}</div>`;}
function attentionRow(iconName,tone,title,copy,status,href,label){return `<article class="attention-row"><span class="attention-icon ${tone}">${icon(iconName)}</span><div><strong>${title}</strong><small>${copy}</small></div><span class="attention-status ${tone}">${status}</span><a href="${href}">${label}</a></article>`;}
function home(){
 const date=today(),[from,to]=monthWindow(),[previousFrom,previousTo]=monthWindow(-1),flow=cashflow(state,from,date),previousFlow=cashflow(state,previousFrom,previousTo),sales=invoiceSales(from,to),previousSales=invoiceSales(previousFrom,previousTo);
 const quotes=list(state,'quotes').filter(r=>['enviada','vencida'].includes(documentStatus(state,r))),orders=list(state,'orders').filter(r=>!['entregado','cancelado'].includes(r.status)),staleOrders=orders.filter(r=>{const changed=(r.updatedAt||r.createdAt||'').slice(0,10);return changed&&Math.floor((new Date(`${date}T12:00:00Z`)-new Date(`${changed}T12:00:00Z`))/86400000)>=3;}),materials=list(state,'materials').filter(r=>r.track),low=materials.filter(r=>stock(state,r.id)<=Number(r.minimum||0));
 const attention=[quotes.length?attentionRow('doc','urgent',`Tienes ${quotes.length} ${quotes.length===1?'cotización':'cotizaciones'} por responder`,'Responde para mantener el interés de tus clientes.','Requiere respuesta','#quotes','Ver cotizaciones'):'',staleOrders.length?attentionRow('clock','warning',`${staleOrders.length} ${staleOrders.length===1?'pedido lleva':'pedidos llevan'} varios días sin actualización`,'Mantén al cliente informado sobre el estado de su pedido.','Más de 3 días','#orders','Revisar pedidos'):'',low.length?attentionRow('box','urgent',`${low.length} ${low.length===1?'material tiene':'materiales tienen'} existencias bajas`,'Evita retrasos en la producción.','Stock bajo','#materials','Ver inventario'):''].filter(Boolean);
 const upcomingEvents=events(state).filter(r=>r.eventDate>=date).slice(0,4),stage={pending:list(state,'orders').filter(r=>r.status==='pendiente').length,progress:list(state,'orders').filter(r=>['en diseño','esperando aprobación','en producción'].includes(r.status)).length,ready:list(state,'orders').filter(r=>r.status==='listo para entregar').length,delivered:list(state,'orders').filter(r=>r.status==='entregado').length},inventory={stock:materials.filter(r=>stock(state,r.id)>Number(r.minimum||0)).length,low:materials.filter(r=>stock(state,r.id)>0&&stock(state,r.id)<=Number(r.minimum||0)).length,out:materials.filter(r=>stock(state,r.id)<=0).length};
 head('Inicio','Esto es lo que necesita tu atención hoy.');
 const attentionHref=quotes.length?'#quotes':staleOrders.length?'#orders':low.length?'#materials':'';
 return `<div class="dashboard-grid"><section class="dashboard-card attention-card">${dashboardTitle('Requiere atención','',attentionHref,'Ver todo')}<div class="attention-list">${attention.join('')||'<div class="attention-clear"><strong>Todo está al día</strong><small>No hay asuntos urgentes con los datos registrados.</small></div>'}</div></section><div class="metrics-row"><article class="metric-card"><span class="metric-icon sales">${icon('statistics')}</span><div><small>Ventas del mes</small><strong>${money(sales)}</strong>${trend(sales,previousSales)}</div></article><article class="metric-card"><span class="metric-icon collected">${icon('money')}</span><div><small>Cobrado</small><strong>${money(flow.income)}</strong>${trend(flow.income,previousFlow.income)}</div></article><article class="metric-card"><span class="metric-icon receivable">${icon('clock')}</span><div><small>Por cobrar</small><strong>${money(flow.receivable)}</strong><span class="trend neutral">Saldo pendiente total</span></div></article><article class="metric-card"><span class="metric-icon expenses">${icon('money')}</span><div><small>Gastos</small><strong>${money(flow.expense)}</strong>${trend(flow.expense,previousFlow.expense)}</div></article></div><div class="dashboard-lower"><section class="dashboard-card today-card">${dashboardTitle('Próximas entregas','Tu agenda y próximos compromisos.','#tasks/calendar','Abrir agenda')}<div class="today-list">${upcomingEvents.length?upcomingEvents.map(r=>upcomingEventRow(r,date)).join(''):'<div class="today-row empty-today"><time>Próximo</time><div><strong>Sin entregas programadas</strong><small>Agrega tus próximos compromisos a la agenda.</small></div></div>'}<a class="add-activity" href="#tasks/new">${icon('plus')}<span>Agregar actividad</span></a></div></section><div class="dashboard-side"><section class="dashboard-card compact-card">${dashboardTitle('Pedidos por etapa','','#orders','Ver todos')}<div class="stage-grid"><div><strong>${stage.pending}</strong><small>Pendientes</small></div><div><strong>${stage.progress}</strong><small>En proceso</small></div><div><strong>${stage.ready}</strong><small>Listos</small></div><div><strong>${stage.delivered}</strong><small>Entregados</small></div></div></section><section class="dashboard-card compact-card">${dashboardTitle('Inventario','','#materials','Ver todos')}<div class="inventory-grid"><div><strong>${inventory.stock}</strong><small>En stock</small></div><div><strong>${inventory.low}</strong><small>Stock bajo</small></div><div><strong>${inventory.out}</strong><small>Sin existencia</small></div></div></section></div></div></div>`;
}
function field(f,data={}){const value=data[f.key]??f.value??'',id='f-'+f.key+'-'+crypto.randomUUID();let control;if(f.type==='textarea')control=`<textarea id="${id}" name="${f.key}" rows="3">${esc(value)}</textarea>`;else if(f.type==='checkbox')control=`<input id="${id}" name="${f.key}" type="checkbox" ${value?'checked':''}>`;else if(['select','ref'].includes(f.type)){const options=f.type==='ref'?[['','Sin seleccionar'],...list(state,f.ref).filter(r=>r.recordType!=='quick-note').map(r=>[r.id,r.number?`${r.number} · ${r.name}`:r.name])]:f.options.map(o=>Array.isArray(o)?o:[o,o]);control=`<select id="${id}" name="${f.key}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>`;}else control=`<input id="${id}" name="${f.key}" type="${f.type}" ${f.type==='file'?'accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm,application/pdf"':`value="${esc(value)}"`} ${f.type==='number'?`step="any" min="${f.min??0}"`:''} ${f.required?'required':''} ${f.type==='url'?'placeholder="https://…"':''}>`;return `<label class="field ${f.type==='textarea'?'wide':''}" for="${id}"><span>${esc(f.label)}${f.required?' *':''}</span>${control}</label>`;}
function lineRow(line={},materials=false){return `<div class="line-row ${materials?'material':''}">${materials?`<label>Material<select data-line="materialId"><option value="">Otro material</option>${list(state,'materials').map(m=>`<option value="${m.id}" ${m.id===line.materialId?'selected':''}>${esc(m.name)}</option>`).join('')}</select><input data-line="description" aria-label="Nombre del material" placeholder="Nombre del material" value="${esc(line.description||'')}"></label>`:`<label>Concepto<input data-line="description" value="${esc(line.description||'')}" required></label>`}<label>Cantidad<input data-line="quantity" type="number" min="0.001" step="any" value="${esc(line.quantity??1)}" required></label><label>${materials?'Costo unitario':'Precio unitario'} RD$<input data-line="${materials?'unitCost':'price'}" type="number" min="0" step="any" value="${esc(line.unitCost??line.price??0)}" required></label><button type="button" data-action="remove-line" aria-label="Quitar este concepto">×</button></div>`;}
function readForm(form,fields){const fd=new FormData(form),data={};for(const f of fields){if(f.type==='file')continue;data[f.key]=f.type==='checkbox'?fd.has(f.key):f.type==='number'?Number(fd.get(f.key)||0):String(fd.get(f.key)||'').trim();if(f.type==='url'&&data[f.key]&&!safeUrl(data[f.key]))throw Error('Utiliza enlaces que comiencen por https:// o http://.');}return data;}
function readLines(){return [...document.querySelectorAll('.line-row')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-line]')].map(el=>[el.dataset.line,el.type==='number'?Number(el.value):el.value])));}
