 clients:[['Información principal',['name','clientType','companyName','contactName','role']],['Contacto',['phone','email','instagram','rnc']],['Relación comercial',['source','preferredChannel','interests','tags','observations']],['Entrega y facturación',['identityNumber','address','sector','city','deliveryReference','deliveryPreference']],['Notas',['notes']]],
 products:[['Información del catálogo',['name','type','category','description']],['Opciones, precio y costos',['variants','pricing','price','calculationId']],['Notas',['notes']]],
