 quotes:[['Información principal',['name','clientId']],['Fechas y referencias',['date','validUntil','due','calculationId']],['Importes de la cotización',['discountType','discount','shipping','taxPercent','advanceType','advance']],['Condiciones y notas',['terms','notes']]],
