 if(action==='create-record'){const kind=button.dataset.kind;if(!schemas[kind])return;button.closest('details')?.removeAttribute('open');notesOpen=false;syncNotesPanelState();if(kind==='clients'){clientType='person';clientDuplicateOverride=false;clientPanelOpen=true;if(route!=='clients'||recordId||mode==='edit'){location.hash='clients';return;}syncClientPanelState(true);return;}if(['quotes','invoices'].includes(kind)){location.hash=`${kind}/new`;return;}createPanelKind=kind;render();$('.creation-panel input:not([type=hidden]),.creation-panel select,.creation-panel textarea')?.focus();return;}
